INSERT INTO products (id, sort, status, name, color, theme, pack, atmo, gallery, i18n, created_at, updated_at) VALUES ('amethyst', 1, 'published', 'Amethyst', '#7A2DB8', '{"bg":"#1E0A2E","bg2":"#0B0414","surface":"#6A1FA8","accent":"#C58BFF","glow":"#9B3DEB"}', 'assets/img/amethyst.webp', 'assets/img/amethyst-atmo.webp', '[{"src":"assets/img/amethyst-photos-2.webp","cap":{"uz":"Asl suratlar: old, orqa va yon tomondan","ru":"Оригинальные фото: спереди, сзади и сбоку","en":"Original photos: front, back and side","ar":"صور أصلية: من الأمام والخلف والجانب"}},{"src":"assets/img/amethyst-photos-1.webp","cap":{"uz":"Asl suratlar: old, burchakdan, orqa, yon va yaqin plan","ru":"Оригинальные фото: спереди, сбоку, сзади и крупным планом","en":"Original photos: front, angle, back, side and close-ups","ar":"صور أصلية: من الأمام والجانب والخلف وعن قرب"}},{"src":"assets/img/amethyst-studio.webp","cap":{"uz":"Har bir qadoqda — 60 ta yuvish","ru":"В каждой упаковке — 60 стирок","en":"60 washes in every pack","ar":"60 غسلة في كل عبوة"}},{"src":"assets/img/amethyst-room.webp","cap":{"uz":"Kir yuvish xonangizda doim qo‘l ostida","ru":"Всегда под рукой в вашей прачечной","en":"Always at hand in your laundry room","ar":"دائمًا في متناول يدك في غرفة الغسيل"}},{"src":"assets/img/amethyst-scent.webp","cap":{"uz":"Ametist va lavanda — chuqur, iliq ifor","ru":"Аметист и лаванда — глубокий, тёплый аромат","en":"Amethyst and lavender — deep and warm","ar":"الجمشت واللافندر — عطر عميق ودافئ"}}]', '{"uz":{"scent":"Ametist va lavanda","line":"Kiyimingizdan kun bo‘yi ketmaydigan ifor","hook":"Kechki ko‘ylak ham ertalabgidek xushbo‘y.","desc":"Amethyst — BÄRC’ning eng chuqur va iliq ifori. U kiyimni ochganingizda emas, kun bo‘yi o‘zini eslatib turadi. Qiyin dog‘ va hidlarga qarshi kuchli, sovuq suvda va qisqa dasturda ham ishlaydi.","for":"Iforni yaqindan sezishni yaxshi ko‘radiganlar uchun: sevimli sviterlar, kechki uchrashuvlar, mehmon kutayotgan uy."},"ru":{"scent":"Аметист и лаванда","line":"Аромат, который остаётся с вами весь день","hook":"Вечером рубашка пахнет так же, как утром.","desc":"Amethyst — самый глубокий и тёплый аромат BÄRC. Он напоминает о себе не только когда вы открываете шкаф, а весь день. Сильный против сложных пятен и запахов, работает в холодной воде и в короткой программе.","for":"Для тех, кто любит чувствовать аромат близко: любимые свитера, вечерние встречи, дом в ожидании гостей."},"en":{"scent":"Amethyst and lavender","line":"A scent that stays with you all day","hook":"Your evening shirt smells like it did this morning.","desc":"Amethyst is BÄRC’s deepest, warmest scent. It doesn’t only greet you when you open the wardrobe — it stays with you all day. Strong on tough stains and odours, and it works in cold water and on short cycles.","for":"For those who love a scent up close: favourite sweaters, evening plans, a home expecting guests."},"ar":{"scent":"الجمشت واللافندر","line":"عطر يرافقك طوال اليوم","hook":"قميص المساء بعطر الصباح نفسه.","desc":"Amethyst هو أعمق عطور BÄRC وأدفؤها. لا يحيّيك فقط عند فتح الخزانة، بل يبقى معك طوال اليوم. قوي ضد البقع والروائح الصعبة، ويعمل في الماء البارد وفي البرامج القصيرة.","for":"لمن يحب أن يشعر بالعطر عن قرب: الكنزات المفضلة، سهرات المساء، بيت ينتظر الضيوف."}}', 1791821754562, 1791821754562);
INSERT INTO products (id, sort, status, name, color, theme, pack, atmo, gallery, i18n, created_at, updated_at) VALUES ('crystal', 2, 'published', 'Crystal Bloom', '#1F5FD9', '{"bg":"#071A45","bg2":"#030A1E","surface":"#1C55D6","accent":"#7DC2FF","glow":"#2F7BFF"}', 'assets/img/crystal.webp', 'assets/img/crystal-atmo.webp', '[{"src":"assets/img/crystal-photos.webp","cap":{"uz":"Asl suratlar: old, burchakdan, orqa, yon va yaqin plan","ru":"Оригинальные фото: спереди, сбоку, сзади и крупным планом","en":"Original photos: front, angle, back, side and close-ups","ar":"صور أصلية: من الأمام والجانب والخلف وعن قرب"}},{"src":"assets/img/crystal-studio.webp","cap":{"uz":"Har bir qadoqda — 60 ta yuvish","ru":"В каждой упаковке — 60 стирок","en":"60 washes in every pack","ar":"60 غسلة في كل عبوة"}},{"src":"assets/img/crystal-room.webp","cap":{"uz":"Kir yuvish xonangizda doim qo‘l ostida","ru":"Всегда под рукой в вашей прачечной","en":"Always at hand in your laundry room","ar":"دائمًا في متناول يدك في غرفة الغسيل"}},{"src":"assets/img/crystal-scent.webp","cap":{"uz":"Gul barglaridek tiniq ifor","ru":"Прозрачный, как лепестки","en":"Clear as petals","ar":"صافٍ كبتلات الزهور"}}]', '{"uz":{"scent":"Gul barglari","line":"Yangi uzilgan gullardek yengil va tiniq","hook":"Shkafni ochasiz — gulzor.","desc":"Crystal Bloom — yengil, tiniq, gulli ifor. Og‘ir emas, bosmaydi — shunchaki “toza” degan his qoldiradi. Dog‘ va hidni ketkazadi, ranglarni yorqin saqlaydi, sovuq suvda ham to‘liq eriydi.","for":"Yengillikni sevadiganlar uchun: kundalik ko‘ylaklar, rangli kiyimlar, yozgi yengil matolar."},"ru":{"scent":"Цветочные лепестки","line":"Лёгкий и прозрачный, как свежие цветы","hook":"Открываете шкаф — а там цветы.","desc":"Crystal Bloom — лёгкий, прозрачный, цветочный. Не тяжёлый и не навязчивый — просто ощущение «чисто». Удаляет пятна и запахи, сохраняет яркость цветов, полностью растворяется даже в холодной воде.","for":"Для тех, кто любит лёгкость: повседневные рубашки, цветные вещи, летние ткани."},"en":{"scent":"Flower petals","line":"Light and clear, like fresh-cut flowers","hook":"Open the wardrobe — find a garden.","desc":"Crystal Bloom is light, clear and floral. Never heavy, never too much — just the feeling of “clean”. It removes stains and odours, keeps colours bright and fully dissolves even in cold water.","for":"For lovers of lightness: everyday shirts, colourful clothes, light summer fabrics."},"ar":{"scent":"بتلات الزهور","line":"خفيف وصافٍ كالزهور المقطوفة للتو","hook":"تفتح الخزانة — فتجد حديقة.","desc":"Crystal Bloom عطر خفيف وصافٍ وزهري. ليس ثقيلًا ولا طاغيًا — مجرد إحساس بالنظافة. يزيل البقع والروائح، ويحافظ على إشراق الألوان، ويذوب تمامًا حتى في الماء البارد.","for":"لمحبي الخفة: القمصان اليومية، الملابس الملونة، أقمشة الصيف الخفيفة."}}', 1791821754562, 1791821754562);
INSERT INTO products (id, sort, status, name, color, theme, pack, atmo, gallery, i18n, created_at, updated_at) VALUES ('original', 3, 'published', 'Original', '#23963F', '{"bg":"#062A1A","bg2":"#02130B","surface":"#1E8A3E","accent":"#8EE58A","glow":"#2FBF55"}', 'assets/img/original.webp', 'assets/img/original-atmo.webp', '[{"src":"assets/img/original-photos.webp","cap":{"uz":"Asl suratlar: old, burchakdan, orqa, yon va yaqin plan","ru":"Оригинальные фото: спереди, сбоку, сзади и крупным планом","en":"Original photos: front, angle, back, side and close-ups","ar":"صور أصلية: من الأمام والجانب والخلف وعن قرب"}},{"src":"assets/img/original-studio.webp","cap":{"uz":"Har bir qadoqda — 60 ta yuvish","ru":"В каждой упаковке — 60 стирок","en":"60 washes in every pack","ar":"60 غسلة في كل عبوة"}},{"src":"assets/img/original-room.webp","cap":{"uz":"Kir yuvish xonangizda doim qo‘l ostida","ru":"Всегда под рукой в вашей прачечной","en":"Always at hand in your laundry room","ar":"دائمًا في متناول يدك في غرفة الغسيل"}},{"src":"assets/img/original-scent.webp","cap":{"uz":"Shudringli yaproqlar tetikligi","ru":"Свежесть листьев в росе","en":"The freshness of dewy leaves","ar":"انتعاش الأوراق المغطاة بالندى"}}]', '{"uz":{"scent":"Yashil yaproqlar","line":"Yomg‘irdan keyingi bog‘dek tetik","hook":"Toza kirning eng to‘g‘ri hidi.","desc":"Original — BÄRC’ning klassik formulasi. Shudringli yaproqlardek tetik ifor va qiyin dog‘larga kuchli ta’sir. Bir marta sinab ko‘rgach, “toza” deganda shu hidni eslaysiz.","for":"Klassikani tanlaydiganlar uchun: oilaviy katta yuvishlar, choyshab va sochiqlar, har kungi kiyim."},"ru":{"scent":"Зелёные листья","line":"Свежий, как сад после дождя","hook":"Тот самый запах чистого белья.","desc":"Original — классическая формула BÄRC. Свежий аромат листьев в росе и сильное действие против сложных пятен. Попробовав раз, вы будете вспоминать именно этот запах, когда слышите слово «чисто».","for":"Для тех, кто выбирает классику: большие семейные стирки, постельное бельё и полотенца, одежда на каждый день."},"en":{"scent":"Green leaves","line":"Fresh as a garden after rain","hook":"The way clean laundry should smell.","desc":"Original is BÄRC’s classic formula: the fresh scent of dewy leaves and strong action on tough stains. Try it once, and this is the smell you’ll think of when someone says “clean”.","for":"For those who choose the classic: big family washes, bed linen and towels, everyday clothes."},"ar":{"scent":"أوراق خضراء","line":"منعش كحديقة بعد المطر","hook":"الرائحة الحقيقية للغسيل النظيف.","desc":"Original هي التركيبة الكلاسيكية من BÄRC: عطر منعش كأوراق يغطيها الندى، وفعالية قوية ضد البقع الصعبة. جرّبها مرة، وستتذكر هذه الرائحة كلما سمعت كلمة «نظيف».","for":"لمن يختار الكلاسيكية: غسلات العائلة الكبيرة، الشراشف والمناشف، ملابس كل يوم."}}', 1791821754562, 1791821754562);
